steps.script:
window.__g={};
(function(){
  var host=document.getElementById('invite-rows');
  var row=document.createElement('div'); row.className='invite-row';
  var main=document.createElement('div'); main.className='invite-row-main';
  main.innerHTML='<div class="invite-row-head">1 — probe</div><div class="invite-row-meta">created x — expires in y</div>';
  var side=document.createElement('div'); side.className='invite-row-side';
  var chip=document.createElement('span'); chip.className='invite-chip'; chip.textContent='Not yet accepted';
  var a=document.createElement('a'); a.className='rm plain link-danger'; a.textContent='Revoke';
  side.append(chip,a); row.append(main,side); host.appendChild(row);
  document.getElementById('invite-list-view').classList.remove('hidden');
  var cr=chip.getBoundingClientRect(), ar=a.getBoundingClientRect();
  var overlap=Math.min(cr.bottom,ar.bottom)-Math.max(cr.top,ar.top);
  // the danger token resolved by the SAME engine — never a literal
  var probe=document.createElement('span'); probe.style.color='var(--danger-link)';
  document.body.appendChild(probe); var want=getComputedStyle(probe).color; probe.remove();
  window.__g={ onOneRow: overlap > 0, tokenMatch: getComputedStyle(a).color === want,
               deco: getComputedStyle(a).textDecorationLine, want: want };
  row.remove();
})();
return JSON.stringify(window.__g);
